@router.post('/install')
async def install_metaskill(req: MetaSkillInstallRequest):
    """安装自定义元技能。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    try:
        import shutil
        from pathlib import Path
        src = Path(req.source)
        if not src.exists():
            return {'success': False, 'error': f'路径不存在: {req.source}'}
        dest = Path(app.config.metaskills_user_dir) / (req.name or src.name)
        shutil.copytree(str(src), str(dest), dirs_exist_ok=True)
        app.metaskills.scan()
        return {'success': True, 'installed': str(dest)}
    except Exception as e:
        return {'success': False, 'error': str(e)}


@router.delete('/{name}')
async def remove_metaskill(name: str):
    """卸载用户元技能。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    import shutil
    from pathlib import Path
    user_dir = Path(app.config.metaskills_user_dir) / name
    if user_dir.exists():
        shutil.rmtree(str(user_dir))
        app.metaskills.scan()
        return {'success': True, 'removed': name}
    return {'success': False, 'error': f'用户元技能 {name} 不存在'}
